#pragma once

#include <binder/IInterface.h>
#include <utils/StrongPointer.h>

namespace android {

/**
 * Wrap an AIDL interface in its DefaultDelegator, or return the existing
 * delegator if |iface| already implements it.
 */
template <typename INTERFACE>
sp<typename INTERFACE::DefaultDelegator> delegate(const sp<INTERFACE>& iface) {
    if (iface == nullptr) {
        return nullptr;
    }

    sp<typename INTERFACE::DefaultDelegator> delegator =
            sp<typename INTERFACE::DefaultDelegator>::cast(iface);
    if (delegator != nullptr) {
        return delegator;
    }

    return sp<typename INTERFACE::DefaultDelegator>(
            new typename INTERFACE::DefaultDelegator(iface));
}

}  // namespace android

/****************************************************************************
 * LCD 提醒显示（郑子轩）
 *
 * CO5300 走 LVGL + /dev/lcd0；告警通过改 LVGL 对象颜色/文字，不用 fb0 填色。
 ****************************************************************************/

#ifndef EDGE_WALKER_ALERT_LCD_H
#define EDGE_WALKER_ALERT_LCD_H

#include "alert_output.h"

#ifdef __cplusplus
extern "C" {
#endif

/* 告警时刷新 LVGL 界面（NONE=深蓝+EW READY，WARN=橙，CRIT=红） */
void alert_lcd_show(ew_alert_level_t level, const char *reason);

/* 上电系统待机（LVGL 开 lcd0 并常驻刷新），用于 rcS: ew boot */
void alert_lcd_boot_splash(void);

/* 接线自检：依次红/绿/蓝/黑，每色约 0.5s；返回 0=fb 可用 */
int alert_lcd_selftest(void);

/* 打印 fb0 分辨率等信息到控制台，返回 0=可用 */
int alert_lcd_info(void);

#ifdef __cplusplus
}
#endif

#endif /* EDGE_WALKER_ALERT_LCD_H */

/****************************************************************************
 * LCD 提醒显示：LVGL on /dev/lcd0（告警改对象，不用 fb0 主路径）
 ****************************************************************************/

#include "alert_lcd.h"

#include <stdio.h>
#include <stdint.h>
#include <string.h>

#ifdef __NuttX__
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <syslog.h>
#include <sys/ioctl.h>
#include <sys/boardctl.h>
#include <nuttx/config.h>
#include <nuttx/video/fb.h>
#ifdef CONFIG_LV_USE_NUTTX
#include <lvgl/lvgl.h>
#endif
#endif

#define EW_FB_DEV "/dev/fb0"
#define EW_ALERT_REQ "/data/ew_alert.req"

#ifdef __NuttX__
#ifdef CONFIG_LV_USE_NUTTX

static lv_obj_t *g_scr;
static lv_obj_t *g_label;
static lv_obj_t *g_reason_label;
static bool g_lvgl_ui_ready;

static void apply_alert_ui(ew_alert_level_t level, const char *reason)
{
  uint32_t bg;
  const char *main_text;

  if (!g_lvgl_ui_ready || g_scr == NULL || g_label == NULL) {
    return;
  }

  switch (level) {
    case EW_ALERT_EMERGENCY:
      bg = 0xFF0000u;
      main_text = "CRIT";
      break;
    case EW_ALERT_SOFT:
    case EW_ALERT_STRONG:
      bg = 0xFFA000u;
      main_text = "WARN";
      break;
    default:
      bg = 0x082060u;
      main_text = "EW READY";
      break;
  }

  lv_obj_set_style_bg_color(g_scr, lv_color_hex(bg), 0);
  lv_obj_set_style_bg_opa(g_scr, LV_OPA_COVER, 0);
  lv_label_set_text(g_label, main_text);
  lv_obj_set_style_text_color(g_label, lv_color_white(), 0);
  lv_obj_center(g_label);

  if (g_reason_label != NULL) {
    if (reason != NULL && reason[0] != '\0' && level != EW_ALERT_NONE) {
      lv_label_set_text(g_reason_label, reason);
      lv_obj_clear_flag(g_reason_label, LV_OBJ_FLAG_HIDDEN);
      lv_obj_align_to(g_reason_label, g_label, LV_ALIGN_OUT_BOTTOM_MID, 0, 8);
    } else {
      lv_obj_add_flag(g_reason_label, LV_OBJ_FLAG_HIDDEN);
    }
  }
}

static void alert_lcd_queue_request(ew_alert_level_t level, const char *reason)
{
  int fd;
  char line[96];

  snprintf(line, sizeof(line), "%d %s\n", (int)level, reason ? reason : "");
  fd = open(EW_ALERT_REQ, O_WRONLY | O_CREAT | O_TRUNC, 0666);
  if (fd < 0) {
    printf("[alert_lcd] queue open failed errno=%d\n", errno);
    fflush(stdout);
    return;
  }
  write(fd, line, strlen(line));
  close(fd);
}

static void alert_lcd_poll_request(void)
{
  int fd;
  char line[96];
  ssize_t n;
  int level_i;
  char reason[64];
  const char *sp;

  fd = open(EW_ALERT_REQ, O_RDONLY);
  if (fd < 0) {
    return;
  }

  n = read(fd, line, sizeof(line) - 1);
  close(fd);
  unlink(EW_ALERT_REQ);
  if (n <= 0) {
    return;
  }

  line[n] = '\0';
  level_i = (int)EW_ALERT_NONE;
  reason[0] = '\0';
  if (sscanf(line, "%d %63[^\n]", &level_i, reason) < 1) {
    return;
  }

  sp = reason;
  while (*sp == ' ') {
    sp++;
  }
  apply_alert_ui((ew_alert_level_t)level_i, sp);
}

#endif /* CONFIG_LV_USE_NUTTX */

#define EW_RGB565(r, g, b) \
  ((uint16_t)(((uint16_t)(r)&0xF8u) << 8) | (((uint16_t)(g)&0xFCu) << 3) | ((uint16_t)(b) >> 3))

static uint16_t rgb565(uint8_t r, uint8_t g, uint8_t b)
{
  return EW_RGB565(r, g, b);
}

static int fb_fill_color(uint16_t color, struct fb_videoinfo_s *vinfo_out)
{
  struct fb_videoinfo_s vinfo;
  struct fb_planeinfo_s pinfo;
  int fd;
  int ret;

  fd = open(EW_FB_DEV, O_RDWR);
  if (fd < 0) {
    return -errno;
  }

  ret = ioctl(fd, FBIOGET_VIDEOINFO, (unsigned long)((uintptr_t)&vinfo));
  if (ret < 0) {
    close(fd);
    return -errno;
  }

  ret = ioctl(fd, FBIOGET_PLANEINFO, (unsigned long)((uintptr_t)&pinfo));
  if (ret < 0) {
    close(fd);
    return -errno;
  }

  if (vinfo_out != NULL) {
    *vinfo_out = vinfo;
  }

  if (pinfo.fbmem != NULL && pinfo.fblen > 0) {
    if (pinfo.bpp == 16) {
      uint16_t *p = (uint16_t *)pinfo.fbmem;
      size_t pixels = pinfo.fblen / 2u;
      for (size_t i = 0; i < pixels; i++) {
        p[i] = color;
      }
    } else if (pinfo.bpp == 32) {
      uint32_t c32 = (uint32_t)color;
      c32 |= (c32 << 16);
      uint32_t *p = (uint32_t *)pinfo.fbmem;
      size_t pixels = pinfo.fblen / 4u;
      for (size_t i = 0; i < pixels; i++) {
        p[i] = c32;
      }
    } else {
      memset(pinfo.fbmem, (color >> 8) & 0xFF, pinfo.fblen);
    }
  }

#ifdef CONFIG_FB_UPDATE
  {
    struct fb_area_s area;

    area.x = 0;
    area.y = 0;
    area.w = vinfo.xres;
    area.h = vinfo.yres;
    ioctl(fd, FBIO_UPDATE, (unsigned long)((uintptr_t)&area));
  }
#endif

  close(fd);
  return 0;
}

#endif /* __NuttX__ */

void alert_lcd_show(ew_alert_level_t level, const char *reason)
{
#ifdef __NuttX__
#ifdef CONFIG_LV_USE_NUTTX
  if (g_lvgl_ui_ready) {
    apply_alert_ui(level, reason);
    printf("[alert_lcd] lvgl level=%d reason=%s\n",
           (int)level, reason ? reason : "");
    fflush(stdout);
    return;
  }

  if (lv_is_initialized()) {
    printf("[alert_lcd] lvgl busy in other task, queue request\n");
    fflush(stdout);
    alert_lcd_queue_request(level, reason);
    return;
  }
#endif

  printf("[alert_lcd] lvgl not ready level=%d reason=%s (queued/no-op)\n",
         (int)level, reason ? reason : "");
  fflush(stdout);
  alert_lcd_queue_request(level, reason);
#else
  (void)level;
  (void)reason;
#endif
}

void alert_lcd_boot_splash(void)
{
#ifdef __NuttX__
#ifdef CONFIG_LV_USE_NUTTX
  lv_nuttx_dsc_t info;
  lv_nuttx_result_t result;
  int ret;
  int lcdfd;

  g_scr = NULL;
  g_label = NULL;
  g_reason_label = NULL;
  g_lvgl_ui_ready = false;

  printf("[ew-boot] splash enter\n");
  fflush(stdout);

  if (lv_is_initialized()) {
    printf("[ew-boot] ERR lv_is_initialized already, abort\n");
    fflush(stdout);
    return;
  }

  ret = boardctl(BOARDIOC_INIT, 0);
  printf("[ew-boot] boardctl ret=%d\n", ret);
  fflush(stdout);
  usleep(200000);

  lcdfd = open("/dev/lcd0", O_RDWR);
  printf("[ew-boot] lcd0 fd=%d errno=%d\n", lcdfd, lcdfd < 0 ? errno : 0);
  fflush(stdout);
  if (lcdfd >= 0) {
    close(lcdfd);
  }

  lv_init();
  lv_nuttx_dsc_init(&info);
#ifdef CONFIG_LV_USE_NUTTX_LCD
  info.fb_path = "/dev/lcd0";
#endif
#ifdef CONFIG_INPUT_TOUCHSCREEN
  info.input_path = "/dev/input0";
#endif
  printf("[ew-boot] lv_nuttx_init fb_path=%s\n",
         info.fb_path ? info.fb_path : "(default fb)");
  fflush(stdout);
  lv_nuttx_init(&info, &result);
  if (result.disp == NULL) {
    printf("[ew-boot] ERR lv_nuttx_init disp=NULL\n");
    fflush(stdout);
    return;
  }

  g_scr = lv_screen_active();
  g_label = lv_label_create(g_scr);
  g_reason_label = lv_label_create(g_scr);
  lv_obj_add_flag(g_reason_label, LV_OBJ_FLAG_HIDDEN);
  g_lvgl_ui_ready = true;
  apply_alert_ui(EW_ALERT_NONE, NULL);

  printf("[ew-boot] OK splash, lv_timer_handler loop\n");
  fflush(stdout);
  for (;;) {
    alert_lcd_poll_request();
    uint32_t idle = lv_timer_handler();
    idle = idle ? idle : 1;
    usleep(idle * 1000);
  }
#else
  printf("[ew-boot] ERR CONFIG_LV_USE_NUTTX not set\n");
  fflush(stdout);
#endif
#endif
}

int alert_lcd_info(void)
{
#ifdef __NuttX__
  struct fb_videoinfo_s vinfo;
  struct fb_planeinfo_s pinfo;
  int fd;
  int ret;

  fd = open(EW_FB_DEV, O_RDWR);
  if (fd < 0) {
    printf("[alert_lcd] %s open failed: %d\n", EW_FB_DEV, errno);
    return 1;
  }

  ret = ioctl(fd, FBIOGET_VIDEOINFO, (unsigned long)((uintptr_t)&vinfo));
  if (ret < 0) {
    printf("[alert_lcd] FBIOGET_VIDEOINFO failed: %d\n", errno);
    close(fd);
    return 1;
  }

  ret = ioctl(fd, FBIOGET_PLANEINFO, (unsigned long)((uintptr_t)&pinfo));
  if (ret < 0) {
    printf("[alert_lcd] FBIOGET_PLANEINFO failed: %d\n", errno);
    close(fd);
    return 1;
  }

  printf("[alert_lcd] %s ok: %ux%u bpp=%u stride=%u fblen=%lu fbmem=%p\n",
         EW_FB_DEV,
         (unsigned)vinfo.xres,
         (unsigned)vinfo.yres,
         (unsigned)pinfo.bpp,
         (unsigned)pinfo.stride,
         (unsigned long)pinfo.fblen,
         pinfo.fbmem);
  close(fd);
  return 0;
#else
  printf("[alert_lcd] host stub\n");
  return 0;
#endif
}

int alert_lcd_selftest(void)
{
#ifdef __NuttX__
#ifdef CONFIG_LV_USE_NUTTX
  if (g_lvgl_ui_ready) {
    apply_alert_ui(EW_ALERT_EMERGENCY, NULL);
    usleep(500000);
    apply_alert_ui(EW_ALERT_SOFT, NULL);
    usleep(500000);
    apply_alert_ui(EW_ALERT_NONE, NULL);
    printf("[alert_lcd] selftest via lvgl R->O->Blue\n");
    return 0;
  }
#endif
  static const struct {
    const char *name;
    uint16_t color;
  } steps[] = {
    {"RED",   0xF800u},
    {"GREEN", 0x07E0u},
    {"BLUE",  0x001Fu},
    {"BLACK", 0x0000u},
  };
  struct fb_videoinfo_s vinfo;
  unsigned i;

  if (fb_fill_color(steps[0].color, &vinfo) < 0) {
    printf("[alert_lcd] selftest: %s not available\n", EW_FB_DEV);
    return 1;
  }

  printf("[alert_lcd] selftest %ux%u — watch screen cycle R/G/B/Black\n",
         (unsigned)vinfo.xres, (unsigned)vinfo.yres);

  for (i = 0; i < (sizeof(steps) / sizeof(steps[0])); i++) {
    fb_fill_color(steps[i].color, NULL);
    printf("[alert_lcd]   -> %s\n", steps[i].name);
    usleep(500000);
  }
  return 0;
#else
  printf("[alert_lcd] host stub selftest\n");
  return 0;
#endif
}

