/****************************************************************************
 * 读 ai_agent config.json，用 curl 调 OpenAI 兼容 chat/completions
 ****************************************************************************/

#include "ew_llm.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#ifdef __NuttX__
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/stat.h>
#endif

#ifndef EW_LLM_CONFIG
#define EW_LLM_CONFIG "/data/ai_agent/config/config.json"
#endif

#define EW_LLM_BODY "/tmp/ew_llm_body.json"
#define EW_LLM_OUT  "/tmp/ew_llm_out.json"

static int read_file(const char *path, char *buf, unsigned sz)
{
  FILE *fp;
  size_t n;

  fp = fopen(path, "r");
  if (fp == NULL) {
    return -1;
  }
  n = fread(buf, 1, sz - 1, fp);
  fclose(fp);
  buf[n] = '\0';
  return (int)n;
}

static int json_str(const char *json, const char *key, char *out, unsigned out_sz)
{
  const char *p;
  char pat[64];
  unsigned i;

  snprintf(pat, sizeof(pat), "\"%s\"", key);
  p = strstr(json, pat);
  if (p == NULL) {
    return -1;
  }
  p = strchr(p + strlen(pat), ':');
  if (p == NULL) {
    return -1;
  }
  p++;
  while (*p == ' ' || *p == '\t') {
    p++;
  }
  if (*p != '"') {
    return -1;
  }
  p++;
  for (i = 0; i + 1 < out_sz && *p != '\0' && *p != '"'; p++) {
    if (*p == '\\' && p[1] != '\0') {
      p++;
      out[i++] = *p;
    } else {
      out[i++] = *p;
    }
  }
  out[i] = '\0';
  return (i > 0) ? 0 : -1;
}

static void json_escape(const char *in, char *out, unsigned out_sz)
{
  unsigned o = 0;

  while (*in != '\0' && o + 2 < out_sz) {
    if (*in == '"' || *in == '\\') {
      out[o++] = '\\';
      out[o++] = *in++;
    } else if ((unsigned char)*in < 0x20) {
      in++;
    } else {
      out[o++] = *in++;
    }
  }
  out[o] = '\0';
}

static int extract_content(const char *json, char *out, unsigned out_sz)
{
  const char *choices;
  const char *err;
  char emsg[160];

  if (json_str(json, "error", emsg, sizeof(emsg)) == 0 && emsg[0] != '\0') {
    snprintf(out, out_sz, "LLM error: %s", emsg);
    return -1;
  }
  err = strstr(json, "\"message\"");
  if (strstr(json, "\"error\"") != NULL && json_str(json, "message", emsg, sizeof(emsg)) == 0) {
    snprintf(out, out_sz, "LLM error: %s", emsg);
    return -1;
  }

  choices = strstr(json, "\"choices\"");
  if (choices == NULL) {
    snprintf(out, out_sz, "bad LLM reply (no choices)");
    return -1;
  }
  if (json_str(choices, "content", out, out_sz) == 0) {
    return 0;
  }
  (void)err;
  snprintf(out, out_sz, "bad LLM reply (no content)");
  return -1;
}

int ew_llm_ask(const char *prompt, char *out, unsigned out_sz)
{
#ifdef __NuttX__
  char cfg[1024];
  char host[128];
  char path[128];
  char port[16];
  char key[160];
  char model[64];
  char url[320];
  char esc[400];
  char cmd[768];
  char body[640];
  FILE *fp;
  int rc;

  if (prompt == NULL || out == NULL || out_sz < 8) {
    return -1;
  }
  out[0] = '\0';

  if (read_file(EW_LLM_CONFIG, cfg, sizeof(cfg)) < 0) {
    snprintf(out, out_sz, "missing %s (adb push MiMo config)", EW_LLM_CONFIG);
    return -1;
  }

  host[0] = path[0] = port[0] = key[0] = model[0] = '\0';
  json_str(cfg, "llm_host", host, sizeof(host));
  json_str(cfg, "llm_path", path, sizeof(path));
  json_str(cfg, "llm_port", port, sizeof(port));
  json_str(cfg, "api_key", key, sizeof(key));
  json_str(cfg, "model", model, sizeof(model));
  if (host[0] == '\0' || key[0] == '\0') {
    snprintf(out, out_sz, "config.json missing llm_host/api_key");
    return -1;
  }
  if (path[0] == '\0') {
    strncpy(path, "/v1/chat/completions", sizeof(path) - 1);
  }
  if (model[0] == '\0') {
    strncpy(model, "mimo-v2.5", sizeof(model) - 1);
  }
  if (strcmp(port, "443") == 0 || port[0] == '\0') {
    snprintf(url, sizeof(url), "https://%s%s", host, path);
  } else {
    snprintf(url, sizeof(url), "https://%s:%s%s", host, port, path);
  }

  json_escape(prompt, esc, sizeof(esc));
  snprintf(body, sizeof(body),
           "{\"model\":\"%s\",\"messages\":["
           "{\"role\":\"system\",\"content\":\"You are Edge Walker (bianyuan xingzhe), "
           "a pedestrian approach-warning assistant on openvela. "
           "Reply in the user's language, briefly.\"},"
           "{\"role\":\"user\",\"content\":\"%s\"}]}",
           model, esc);

  mkdir("/tmp", 0755);
  fp = fopen(EW_LLM_BODY, "w");
  if (fp == NULL) {
    snprintf(out, out_sz, "cannot write %s", EW_LLM_BODY);
    return -1;
  }
  fputs(body, fp);
  fclose(fp);
  unlink(EW_LLM_OUT);

  snprintf(cmd, sizeof(cmd),
           "curl -sS --connect-timeout 15 --max-time 50 "
           "-X POST '%s' "
           "-H 'Authorization: Bearer %s' "
           "-H 'Content-Type: application/json' "
           "-d @%s -o %s",
           url, key, EW_LLM_BODY, EW_LLM_OUT);

  rc = system(cmd);
  if (rc != 0) {
    snprintf(out, out_sz, "curl failed rc=%d (check network / curl)", rc);
    return -1;
  }
  if (read_file(EW_LLM_OUT, cfg, sizeof(cfg)) < 8) {
    snprintf(out, out_sz, "empty LLM response");
    return -1;
  }
  return extract_content(cfg, out, out_sz);
#else
  snprintf(out, out_sz, "host stub: %s", prompt ? prompt : "");
  return 0;
#endif
}

