  apply_font(lab);
  lv_label_set_text(lab, label);
  lv_obj_center(lab);
  lv_obj_set_style_bg_color(btn, lv_color_hex(0x3D4F7C), 0);
  lv_obj_add_event_cb(btn, chip_clicked, LV_EVENT_CLICKED, (void *)label);
}

static void build_ui(void)
{
