static void poll_reply(void)
{
  lv_obj_t *last;

  if (!g_reply_ready) {
    return;
  }
  g_reply_ready = 0;
  g_busy = 0;
  last = lv_obj_get_child(g_list, (int32_t)(lv_obj_get_child_count(g_list) - 1));
  if (last != NULL) {
    lv_obj_delete(last);
  }
  add_bubble(g_reply[0] != '\0' ? g_reply : "(empty reply)", false);
}

