/****************************************************************************
 * 读 ai_agent config.json；goldfish 先拉起 eth0，再 posix_spawn curl
 ****************************************************************************/

#include "ew_llm.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#ifdef __NuttX__
#include <unistd.h>
#include <sys/stat.h>
#include <sys/wait.h>
#include <spawn.h>
#include <nuttx/config.h>
#endif

#ifndef EW_LLM_CONFIG
#define EW_LLM_CONFIG "/data/ai_agent/config/config.json"
#endif

#define EW_LLM_BODY "/tmp/ew_llm_body.json"
#define EW_LLM_OUT  "/tmp/ew_llm_out.json"

static int read_file(const char *path, char *buf, unsigned sz)
{
  FILE *fp;
  size_t n;

  fp = fopen(path, "r");
  if (fp == NULL) {
    return -1;
  }
  n = fread(buf, 1, sz - 1, fp);
  fclose(fp);
  buf[n] = '\0';
  return (int)n;
}

static int json_str(const char *json, const char *key, char *out, unsigned out_sz)
{
  const char *p;
  char pat[64];
  unsigned i;

  snprintf(pat, sizeof(pat), "\"%s\"", key);
  p = strstr(json, pat);
  if (p == NULL) {
    return -1;
  }
  p = strchr(p + strlen(pat), ':');
  if (p == NULL) {
    return -1;
  }
  p++;
  while (*p == ' ' || *p == '\t') {
    p++;
  }
  if (*p != '"') {
    return -1;
  }
  p++;
  for (i = 0; i + 1 < out_sz && *p != '\0' && *p != '"'; p++) {
    if (*p == '\\' && p[1] != '\0') {
      p++;
      out[i++] = *p;
    } else {
      out[i++] = *p;
    }
  }
  out[i] = '\0';
  return (i > 0) ? 0 : -1;
}

static void json_escape(const char *in, char *out, unsigned out_sz)
{
  unsigned o = 0;

  while (*in != '\0' && o + 2 < out_sz) {
    if (*in == '"' || *in == '\\') {
      out[o++] = '\\';
      out[o++] = *in++;
    } else if ((unsigned char)*in < 0x20) {
      in++;
    } else {
      out[o++] = *in++;
    }
  }
  out[o] = '\0';
}

static int extract_content(const char *json, char *out, unsigned out_sz)
{
  const char *choices;
  char emsg[160];

  if (strstr(json, "\"error\"") != NULL &&
      json_str(json, "message", emsg, sizeof(emsg)) == 0) {
    snprintf(out, out_sz, "LLM error: %s", emsg);
    return -1;
  }

  choices = strstr(json, "\"choices\"");
  if (choices == NULL) {
    snprintf(out, out_sz, "bad LLM reply (no choices)");
    return -1;
  }
  if (json_str(choices, "content", out, out_sz) == 0) {
    return 0;
  }
  snprintf(out, out_sz, "bad LLM reply (no content)");
  return -1;
}

#ifdef __NuttX__
static void ensure_net(void)
{
#ifdef CONFIG_ARCH_CHIP_GOLDFISH_ARM64
  /* qemu user NAT：DHCP 经常拿不到地址，写死 goldfish 默认网 */
  system("ifup eth0");
  system("ifconfig eth0 10.0.2.15 netmask 255.255.255.0");
  system("ifconfig eth0 dr 10.0.2.2");
  system("ifconfig eth0 dns 10.0.2.3");
#else
  system("ifup eth0");
  system("ifup wlan0");
#endif
}

static int spawn_curl(char *const argv[])
{
  posix_spawnattr_t attr;
  pid_t pid;
  int rc;
  int err;

  posix_spawnattr_init(&attr);
  posix_spawnattr_setstacksize(&attr, 65536);
  err = posix_spawn(&pid, "/bin/curl", NULL, &attr, argv, NULL);
  posix_spawnattr_destroy(&attr);
  if (err != 0) {
    return -err;
  }
  if (waitpid(pid, &rc, 0) < 0) {
    return -1;
  }
  if (WIFEXITED(rc)) {
    return WEXITSTATUS(rc);
  }
  return -1;
}
#endif

int ew_llm_ask(const char *prompt, char *out, unsigned out_sz)
{
#ifdef __NuttX__
  char cfg[4096];
  char host[128];
  char path[128];
  char port[16];
  char key[160];
  char model[64];
  char url[320];
  char esc[400];
  char body[640];
  char auth[220];
  FILE *fp;
  int rc;
  char *argv[20];
  int i;

  if (prompt == NULL || out == NULL || out_sz < 8) {
    return -1;
  }
  out[0] = '\0';

  ensure_net();

  if (read_file(EW_LLM_CONFIG, cfg, sizeof(cfg)) < 0) {
    snprintf(out, out_sz, "missing %s (adb push MiMo config)", EW_LLM_CONFIG);
    return -1;
  }

  host[0] = path[0] = port[0] = key[0] = model[0] = '\0';
  json_str(cfg, "llm_host", host, sizeof(host));
  json_str(cfg, "llm_path", path, sizeof(path));
  json_str(cfg, "llm_port", port, sizeof(port));
  json_str(cfg, "api_key", key, sizeof(key));
  json_str(cfg, "model", model, sizeof(model));
  if (host[0] == '\0' || key[0] == '\0') {
    snprintf(out, out_sz, "config.json missing llm_host/api_key");
    return -1;
  }
  if (path[0] == '\0') {
    strncpy(path, "/v1/chat/completions", sizeof(path) - 1);
  }
  if (model[0] == '\0') {
    strncpy(model, "mimo-v2.5", sizeof(model) - 1);
  }
  if (strcmp(port, "443") == 0 || port[0] == '\0') {
    snprintf(url, sizeof(url), "https://%s%s", host, path);
  } else {
    snprintf(url, sizeof(url), "https://%s:%s%s", host, port, path);
  }

  json_escape(prompt, esc, sizeof(esc));
  snprintf(body, sizeof(body),
           "{\"model\":\"%s\",\"messages\":["
           "{\"role\":\"system\",\"content\":\"You are Edge Walker, a pedestrian "
           "approach-warning assistant on openvela. Reply briefly in the user's language.\"},"
           "{\"role\":\"user\",\"content\":\"%s\"}]}",
           model, esc);

  mkdir("/tmp", 0755);
  fp = fopen(EW_LLM_BODY, "w");
  if (fp == NULL) {
    snprintf(out, out_sz, "cannot write %s", EW_LLM_BODY);
    return -1;
  }
  fputs(body, fp);
  fclose(fp);
  unlink(EW_LLM_OUT);

  snprintf(auth, sizeof(auth), "Authorization: Bearer %s", key);
  i = 0;
  argv[i++] = "curl";
  argv[i++] = "-sS";
  argv[i++] = "--connect-timeout";
  argv[i++] = "15";
  argv[i++] = "--max-time";
  argv[i++] = "50";
  argv[i++] = "-X";
  argv[i++] = "POST";
  argv[i++] = url;
  argv[i++] = "-H";
  argv[i++] = auth;
  argv[i++] = "-H";
  argv[i++] = "Content-Type: application/json";
  argv[i++] = "-d";
  argv[i++] = "@" EW_LLM_BODY;
  argv[i++] = "-o";
  argv[i++] = EW_LLM_OUT;
  argv[i++] = NULL;

  rc = spawn_curl(argv);
  if (rc != 0) {
    snprintf(out, out_sz, "curl exit %d (net/DNS/TLS)", rc);
    return -1;
  }
  if (read_file(EW_LLM_OUT, cfg, sizeof(cfg)) < 8) {
    snprintf(out, out_sz, "empty LLM response");
    return -1;
  }
  return extract_content(cfg, out, out_sz);
#else
  snprintf(out, out_sz, "host stub: %s", prompt ? prompt : "");
  return 0;
#endif
}

/****************************************************************************
 * LVGL 智能体对话：点按快捷句 + 中/英键盘（无语音）
 ****************************************************************************/

#include "ew_chat.h"
#include "ew_llm.h"

#include <stdio.h>
#include <string.h>
#include <stdbool.h>
#include <ctype.h>

#ifdef __NuttX__
#include <pthread.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/boardctl.h>
#include <nuttx/config.h>
#ifdef CONFIG_LV_USE_NUTTX
#include <lvgl/lvgl.h>
#if LV_USE_FREETYPE
#include <lvgl/src/libs/freetype/lv_freetype.h>
#endif
#endif
#endif

#define EW_CHAT_MAX_BUBBLE 12
#define EW_CHAT_TEXT_MAX 512

#ifdef __NuttX__
#ifdef CONFIG_LV_USE_NUTTX

typedef struct {
  const char *py;
  const char *zh;
} ew_py_t;

/* 常用拼音词，按长词优先匹配 */
static const ew_py_t g_py_dict[] = {
  {"weishenme", "为什么"}, {"zenmeyang", "怎么样"},
  {"gaojing", "告警"}, {"jingbao", "警报"},
  {"juli", "距离"}, {"leida", "雷达"},
  {"zhuangtai", "状态"}, {"xianzai", "现在"},
  {"jieshao", "介绍"}, {"bangzhu", "帮助"},
  {"nihao", "你好"}, {"shenme", "什么"},
  {"zenme", "怎么"}, {"zenmeban", "怎么办"},
  {"xiexie", "谢谢"}, {"duibuqi", "对不起"},
  {"keyi", "可以"}, {"buneng", "不能"},
  {"kaiguan", "开关"}, {"yujing", "预警"},
  {"jinji", "紧急"}, {"anquan", "安全"},
  {"xingren", "行人"}, {"dianche", "电车"},
  {"jieshi", "解释"}, {"gongzuo", "工作"},
  {"nashi", "那是"}, {"zheshi", "这是"},
  {"woshi", "我是"}, {"nishi", "你是"},
  {"hao", "好"}, {"ni", "你"}, {"wo", "我"},
  {"de", "的"}, {"le", "了"}, {"ma", "吗"},
  {"a", "啊"}, {"ba", "吧"}, {"ne", "呢"},
  {"shi", "是"}, {"bu", "不"}, {"you", "有"},
  {"mei", "没"}, {"zai", "在"}, {"he", "和"},
  {NULL, NULL}
};

static lv_obj_t *g_scr;
static lv_obj_t *g_status;
static lv_obj_t *g_list;
static lv_obj_t *g_ta;
static lv_obj_t *g_kb;
static lv_obj_t *g_ime_bar;
static lv_obj_t *g_py_lab;
static lv_obj_t *g_cands[5];
static lv_obj_t *g_lang_btn;
static lv_obj_t *g_wait_bubble;
static lv_font_t *g_font;
static volatile int g_busy;
static char g_pending[256];
static char g_reply[EW_CHAT_TEXT_MAX];
static volatile int g_reply_ready;
static bool g_zh;
static char g_py[24];

static const char *g_font_paths[] = {
  "/data/font/MiSans-Regular.ttf",
  "/data/MiSans-Regular.ttf",
  NULL
};

static lv_font_t *try_cjk_font(uint32_t size)
{
#if LV_USE_FREETYPE
  int i;

  /* lv_init 可能已 init；失败也继续 create */
  (void)lv_freetype_init(128);
  for (i = 0; g_font_paths[i] != NULL; i++) {
    if (access(g_font_paths[i], R_OK) != 0) {
      continue;
    }
    lv_font_t *f = lv_freetype_font_create(g_font_paths[i],
                                           LV_FREETYPE_FONT_RENDER_MODE_BITMAP,
                                           size,
                                           LV_FREETYPE_FONT_STYLE_NORMAL);
    if (f != NULL) {
      printf("[ew-chat] font %s @%u\n", g_font_paths[i], (unsigned)size);
      return f;
    }
  }
  printf("[ew-chat] CJK font not loaded\n");
#else
  (void)size;
#endif
  return NULL;
}

static void apply_font(lv_obj_t *obj)
{
  if (g_font != NULL) {
    lv_obj_set_style_text_font(obj, g_font, 0);
  }
}

static void hide_kb(void)
{
  if (g_kb != NULL) {
    lv_obj_add_flag(g_kb, LV_OBJ_FLAG_HIDDEN);
  }
  if (g_ime_bar != NULL) {
    lv_obj_add_flag(g_ime_bar, LV_OBJ_FLAG_HIDDEN);
  }
}

static void show_kb(void)
{
  if (g_kb != NULL) {
    lv_obj_clear_flag(g_kb, LV_OBJ_FLAG_HIDDEN);
  }
  if (g_zh && g_ime_bar != NULL) {
    lv_obj_clear_flag(g_ime_bar, LV_OBJ_FLAG_HIDDEN);
  }
}

static void add_bubble(const char *text, bool user)
{
  lv_obj_t *row;
  lv_obj_t *lab;
  lv_color_t bg;

  if (g_list == NULL || text == NULL) {
    return;
  }

  while (lv_obj_get_child_count(g_list) >= EW_CHAT_MAX_BUBBLE) {
    lv_obj_t *old = lv_obj_get_child(g_list, 0);
    if (old != NULL) {
      if (old == g_wait_bubble) {
        g_wait_bubble = NULL;
      }
      lv_obj_delete(old);
    } else {
      break;
    }
  }

  row = lv_obj_create(g_list);
  lv_obj_set_width(row, lv_pct(user ? 88 : 92));
  lv_obj_set_height(row, LV_SIZE_CONTENT);
  lv_obj_set_style_radius(row, 12, 0);
  lv_obj_set_style_border_width(row, 0, 0);
  lv_obj_set_style_pad_all(row, 10, 0);
  bg = user ? lv_color_hex(0x1E5AA8) : lv_color_hex(0x2A2F4A);
  lv_obj_set_style_bg_color(row, bg, 0);
  lv_obj_set_style_bg_opa(row, LV_OPA_COVER, 0);
  if (user) {
    lv_obj_set_style_margin_left(row, 40, 0);
  }

  lab = lv_label_create(row);
  apply_font(lab);
  lv_label_set_long_mode(lab, LV_LABEL_LONG_WRAP);
  lv_obj_set_width(lab, lv_pct(100));
  lv_label_set_text(lab, text);
  lv_obj_set_style_text_color(lab, lv_color_white(), 0);
  lv_obj_scroll_to_view(row, LV_ANIM_ON);
}

static const char *local_reply(const char *q)
{
  if (q == NULL) {
    return NULL;
  }
  if (strstr(q, "Who are you") || strstr(q, "你是谁") || strstr(q, "介绍")) {
    return "I am Edge Walker agent: local radar warning + cloud Q&A. No voice on DevKit.";
  }
  if (strstr(q, "alert") || strstr(q, "告警") || strstr(q, "How does")) {
    return "Radar on UART2. Near+fast -> WARN orange / CRIT red. Offline safe loop does not need LLM.";
  }
  if (strstr(q, "EW READY") || strstr(q, "READY")) {
    return "EW READY = idle, no approach alert. Orange WARN, red CRIT.";
  }
  if (strcmp(q, "Hello") == 0 || strcmp(q, "你好") == 0) {
    return "Hello. Tap a chip or type. Keyboard hides when you tap the chat area.";
  }
  return NULL;
}

static void *ask_thread(void *arg)
{
  (void)arg;
  g_reply[0] = '\0';
  if (ew_llm_ask(g_pending, g_reply, sizeof(g_reply)) != 0) {
    const char *fb = local_reply(g_pending);
    if (fb != NULL) {
      snprintf(g_reply, sizeof(g_reply), "%s", fb);
    }
  }
  g_reply_ready = 1;
  return NULL;
}

static void start_ask(const char *text)
{
  pthread_t th;
  pthread_attr_t attr;
  const char *p;

  if (text == NULL || g_busy) {
    return;
  }
  while (*text == ' ') {
    text++;
  }
  if (text[0] == '\0') {
    return;
  }

  strncpy(g_pending, text, sizeof(g_pending) - 1);
  g_pending[sizeof(g_pending) - 1] = '\0';
  add_bubble(g_pending, true);
  add_bubble("...", false);
  g_wait_bubble = lv_obj_get_child(g_list,
                                  (int32_t)(lv_obj_get_child_count(g_list) - 1));
  g_busy = 1;
  g_reply_ready = 0;
  if (g_status != NULL) {
    lv_label_set_text(g_status, "thinking...  (eth0 + MiMo)");
  }
  hide_kb();

  p = local_reply(g_pending);
  pthread_attr_init(&attr);
  pthread_attr_setstacksize(&attr, 65536);
  if (pthread_create(&th, &attr, ask_thread, NULL) != 0) {
    if (ew_llm_ask(g_pending, g_reply, sizeof(g_reply)) != 0 && p != NULL) {
      snprintf(g_reply, sizeof(g_reply), "%s", p);
    }
    g_reply_ready = 1;
  } else {
    pthread_detach(th);
  }
  pthread_attr_destroy(&attr);
}

static void send_from_ta(void)
{
  const char *t;

  if (g_ta == NULL) {
    return;
  }
  t = lv_textarea_get_text(g_ta);
  start_ask(t);
  lv_textarea_set_text(g_ta, "");
  g_py[0] = '\0';
}

static void refresh_cands(void)
{
  int n = 0;
  int i;

  if (g_py_lab != NULL) {
    lv_label_set_text_fmt(g_py_lab, "py: %s", g_py[0] ? g_py : "_");
  }
  for (i = 0; i < 5; i++) {
    if (g_cands[i] != NULL) {
      lv_obj_add_flag(g_cands[i], LV_OBJ_FLAG_HIDDEN);
    }
  }
  if (g_py[0] == '\0') {
    return;
  }
  for (i = 0; g_py_dict[i].py != NULL && n < 5; i++) {
    if (strncmp(g_py_dict[i].py, g_py, strlen(g_py)) == 0) {
      lv_obj_t *lab = lv_obj_get_child(g_cands[n], 0);
      if (lab != NULL) {
        lv_label_set_text(lab, g_py_dict[i].zh);
      }
      lv_obj_clear_flag(g_cands[n], LV_OBJ_FLAG_HIDDEN);
      lv_obj_set_user_data(g_cands[n], (void *)g_py_dict[i].zh);
      n++;
    }
  }
}

static void commit_zh(const char *zh)
{
  if (g_ta == NULL || zh == NULL) {
    return;
  }
  lv_textarea_add_text(g_ta, zh);
  g_py[0] = '\0';
  refresh_cands();
}

static void cand_clicked(lv_event_t *e)
{
  lv_obj_t *btn = lv_event_get_target(e);
  commit_zh((const char *)lv_obj_get_user_data(btn));
}

static void handle_zh_key(const char *txt)
{
  size_t n;

  if (txt == NULL || txt[0] == '\0') {
    return;
  }
  if (strcmp(txt, LV_SYMBOL_BACKSPACE) == 0 || strcmp(txt, "Del") == 0) {
    n = strlen(g_py);
    if (n > 0) {
      g_py[n - 1] = '\0';
      refresh_cands();
    } else if (g_ta != NULL) {
      lv_textarea_delete_char(g_ta);
    }
    return;
  }
  if (strcmp(txt, " ") == 0 || strcmp(txt, LV_SYMBOL_NEW_LINE) == 0) {
    if (g_cands[0] != NULL && !lv_obj_has_flag(g_cands[0], LV_OBJ_FLAG_HIDDEN)) {
      commit_zh((const char *)lv_obj_get_user_data(g_cands[0]));
    } else if (g_py[0] != '\0') {
      lv_textarea_add_text(g_ta, g_py);
      g_py[0] = '\0';
      refresh_cands();
    }
    return;
  }
  if (strcmp(txt, LV_SYMBOL_OK) == 0 || strcmp(txt, "Enter") == 0) {
    if (g_py[0] != '\0' && g_cands[0] != NULL &&
        !lv_obj_has_flag(g_cands[0], LV_OBJ_FLAG_HIDDEN)) {
      commit_zh((const char *)lv_obj_get_user_data(g_cands[0]));
    }
    send_from_ta();
    return;
  }
  if (txt[0] >= 'a' && txt[0] <= 'z' && txt[1] == '\0') {
    n = strlen(g_py);
    if (n + 1 < sizeof(g_py)) {
      g_py[n] = txt[0];
      g_py[n + 1] = '\0';
      refresh_cands();
    }
    return;
  }
  if (txt[0] >= 'A' && txt[0] <= 'Z' && txt[1] == '\0') {
    n = strlen(g_py);
    if (n + 1 < sizeof(g_py)) {
      g_py[n] = (char)tolower((int)txt[0]);
      g_py[n + 1] = '\0';
      refresh_cands();
    }
    return;
  }
}

static void kb_event(lv_event_t *e)
{
  lv_event_code_t code = lv_event_get_code(e);
  uint32_t id;
  const char *txt;

  if (code == LV_EVENT_READY || code == LV_EVENT_CANCEL) {
    hide_kb();
    return;
  }
  if (code != LV_EVENT_VALUE_CHANGED || !g_zh) {
    return;
  }
  id = lv_buttonmatrix_get_selected_button(g_kb);
  txt = lv_buttonmatrix_get_button_text(g_kb, id);
  handle_zh_key(txt);
}

