static void poll_reply(void)
{
  if (!g_reply_ready) {
    return;
  }
  g_reply_ready = 0;
  g_busy = 0;
  if (g_wait_bubble != NULL) {
    lv_obj_delete(g_wait_bubble);
    g_wait_bubble = NULL;
  }
  add_bubble(g_reply[0] != '\0' ? g_reply : "(empty)", false);
  if (g_status != NULL) {
    lv_label_set_text(g_status, "EW READY | tap chip, or ZH/EN keyboard (no voice)");
  }
}

