static int has_cjk(const char *s)
{
  const unsigned char *p = (const unsigned char *)s;

  if (p == NULL) {
    return 0;
  }
  while (*p != '\0') {
    if (*p >= 0xE0) {
      return 1;
    }
    p++;
  }
  return 0;
}

