/* 去掉 emoji（4 字节 UTF-8），保留中文 */
static void sanitize_reply(char *s)
{
  unsigned char *r;
  unsigned char *w;
  int n;

  if (s == NULL) {
    return;
  }
  r = (unsigned char *)s;
  w = r;
  while (*r != '\0') {
    if (*r < 0x80) {
      *w++ = *r++;
    } else if (*r >= 0xF0) {
      n = (*r >= 0xF8) ? 5 : 4;
      while (n-- > 0 && *r != '\0') {
        r++;
      }
    } else if (*r >= 0xE0) {
      n = 3;
      while (n-- > 0 && *r != '\0') {
        *w++ = *r++;
      }
    } else {
      n = 2;
      while (n-- > 0 && *r != '\0') {
        *w++ = *r++;
      }
    }
  }
  *w = '\0';
}

