      g_scr = NULL;
      g_status = NULL;
      g_list = NULL;
      g_ta = NULL;
      g_kb = NULL;
      g_ime_bar = NULL;
      g_wait_bubble = NULL;
      g_busy = 0;
      g_reply_ready = 0;
      g_leave_chat = 0;
      build_ui();
      printf("[ew-ui] chat page\n");
      fflush(stdout);
      while (!g_leave_chat) {
        poll_reply();
        {
          uint32_t idle = lv_timer_handler();
          idle = idle ? idle : 1;
          usleep(idle * 1000);
        }
      }
      hide_kb();
      mode = 0;
    } else {
      alert_lcd_attach_warn_ui();
      printf("[ew-ui] warn page\n");
      fflush(stdout);
      while (!alert_lcd_want_chat()) {
        alert_lcd_warn_tick();
        {
          uint32_t idle = lv_timer_handler();
          idle = idle ? idle : 1;
          usleep(idle * 1000);
        }
      }
      alert_lcd_detach_warn_ui();
      mode = 1;
    }
  }
#else
  (void)start_in_chat;
#endif
#else
  (void)start_in_chat;
#endif
}

