static char g_wifi_boot_status[40];
static volatile int g_wifi_boot_tried;
static volatile int g_wifi_boot_done;

static void on_chat_btn(lv_event_t *e)
{
  (void)e;
  g_want_chat = 1;
}

static void *wifi_boot_thread(void *arg)
{
  (void)arg;
  ew_wifi_bringup(g_wifi_boot_status, sizeof(g_wifi_boot_status));
  g_wifi_boot_done = 1;
  return NULL;
}

static void wifi_boot_start(void)
{
  pthread_t th;
  pthread_attr_t attr;

  if (g_wifi_boot_tried) {
    return;
  }
  g_wifi_boot_tried = 1;
  pthread_attr_init(&attr);
  pthread_attr_setstacksize(&attr, 8192);
  if (pthread_create(&th, &attr, wifi_boot_thread, NULL) != 0) {
    printf("[ew-at] wifi thread fail, sync bringup\n");
    fflush(stdout);
    ew_wifi_bringup(g_wifi_boot_status, sizeof(g_wifi_boot_status));
    g_wifi_boot_done = 1;
  } else {
    pthread_detach(th);
  }
  pthread_attr_destroy(&attr);
}

static void wifi_boot_apply_status(void)
{
  if (g_wifi_boot_done != 1 || !g_lvgl_ui_ready) {
    return;
  }
  g_wifi_boot_done = 2;
  if (g_wifi_boot_status[0] != '\0') {
    char line[48];
    snprintf(line, sizeof(line), "R %s", g_wifi_boot_status);
    apply_alert_ui(EW_ALERT_NONE, line);
  }
}

