input.new_string:
static void ft6146_map_xy(struct ft6146_touch_lowerhalf_s *ft6146)
{
  uint16_t x = ft6146->last_x;
  uint16_t y = ft6146->last_y;
  uint32_t den;

  /* 面板 390×450；若 IC 报 12bit/10bit 则按比例缩到屏坐标 */
  if (x >= 512 || y >= 512)
    {
      den = (x < 2048 && y < 2048) ? 1023u : 4095u;
      x = (uint16_t)((uint32_t)x * 389u / den);
      y = (uint16_t)((uint32_t)y * 449u / den);
    }

  ft6146->last_x = x;
  ft6146->last_y = y;
}

static void ft6146_data_worker(void *param)
{
  struct ft6146_touch_lowerhalf_s *ft6146 =
    (struct ft6146_touch_lowerhalf_s *)param;
  struct touch_sample_s sample;
  uint8_t buf[5] = {0};
  uint8_t touch_num;
  bool down;
  int ret;

  ret = ft6146_i2c_read(ft6146->i2c, FT6146_REG_TD_STATUS, buf, sizeof(buf));
  if (ret < 0)
    {
      return;
    }

  touch_num = buf[0] & 0x0f;
  down = (touch_num > 0);

  if (!down && !ft6146->was_down)
    {
      return;
    }

  nxmutex_lock(&ft6146->devlock);

  memset(&sample, 0, sizeof(sample));
  sample.npoints = 1;
  sample.point[0].id = 0;

  if (down)
    {
      ft6146->last_x = ((uint16_t)(buf[1] & 0x0f) << 8) | buf[2];
      ft6146->last_y = ((uint16_t)(buf[3] & 0x0f) << 8) | buf[4];
      ft6146_map_xy(ft6146);
      sample.point[0].flags = (ft6146->was_down ? TOUCH_MOVE : TOUCH_DOWN) |
                              TOUCH_ID_VALID | TOUCH_POS_VALID;
    }
  else
    {
      sample.point[0].flags = TOUCH_UP | TOUCH_ID_VALID;
    }

  sample.point[0].x = ft6146->last_x;
  sample.point[0].y = ft6146->last_y;
  ft6146->was_down = down;

  {
    static int s_tp_log;
    if (s_tp_log < 16)
      {
        s_tp_log++;
        syslog(LOG_INFO, "ft6146: %s x=%u y=%u n=%u\n",
               down ? "down" : "up",
               ft6146->last_x, ft6146->last_y, touch_num);
      }
  }

  touch_event(ft6146->lower.priv, &sample);
  nxmutex_unlock(&ft6146->devlock);
}

static void ft6146_poll_worker(void *param)
{
  struct ft6146_touch_lowerhalf_s *ft6146 =
    (struct ft6146_touch_lowerhalf_s *)param;

  ft6146_data_worker(ft6146);
  (void)work_queue(LPWORK, &ft6146->pollwork, ft6146_poll_worker, ft6146,
                   MSEC2TICK(20));
}

