#ifndef EDGE_WALKER_EW_WIFI_AT_H
#define EDGE_WALKER_EW_WIFI_AT_H

#ifdef __cplusplus
extern "C" {
#endif

#ifndef EW_WIFI_AT_DEV
#define EW_WIFI_AT_DEV "/dev/ttyS2"
#endif

int ew_wifi_at_ping(void);
int ew_wifi_at_cmd(const char *at_line);
int ew_wifi_at_status(void);
/* 开机：测 AT，若已配置 SSID 则 CWJAP。out 写入屏上短状态（无密码）。 */
int ew_wifi_bringup(char *out, unsigned out_sz);

/* ESP AT SSL + HTTP POST。resp 为模组回灌（含 HTTP 头）。成功 0。 */
int ew_wifi_http_ssl_post(const char *host, unsigned port, const char *path,
                          const char *bearer, const char *json_body,
                          char *resp, unsigned resp_sz);

#ifdef __cplusplus
}
#endif

#endif

/****************************************************************************
 * UART AT 猫：PA24/PA25 → /dev/ttyS2 @ 115200
 * 无 SSID 时走 ESP-Touch SmartConfig（屏显 SMART，用乐鑫 Esptouch 配网）
 * LLM 走同一串口：CIPSTART SSL + CIPSEND HTTP POST（不依赖板载 curl）
 ****************************************************************************/

#include "ew_wifi_at.h"
#include "ew_wifi_secret.h"

#include <stdio.h>
#include <string.h>
#include <errno.h>
#include <pthread.h>

#ifdef __NuttX__
#include <fcntl.h>
#include <unistd.h>
#include <termios.h>
#include <nuttx/config.h>
#endif

#ifdef __NuttX__

static pthread_mutex_t g_at_mu = PTHREAD_MUTEX_INITIALIZER;

static void at_lock(void)
{
  pthread_mutex_lock(&g_at_mu);
}

static void at_unlock(void)
{
  pthread_mutex_unlock(&g_at_mu);
}

static void print_rx(const char *s)
{
  char line[200];
  unsigned i;
  unsigned o = 0;

  if (s == NULL) {
    printf("[ew-at] rx=\n");
    return;
  }
  for (i = 0; s[i] != '\0' && o + 1 < sizeof(line); i++) {
    char c = s[i];
    if (c == '\r' || c == '\n') {
      c = ' ';
    } else if ((unsigned char)c < 32u || (unsigned char)c > 126u) {
      c = '.';
    }
    line[o++] = c;
  }
  line[o] = '\0';
  printf("[ew-at] rx=%s\n", line);
  fflush(stdout);
}

static int uart_open(void)
{
  struct termios tio;
  int fd;

  fd = open(EW_WIFI_AT_DEV, O_RDWR | O_NOCTTY);
  if (fd < 0) {
    printf("[ew-at] open %s failed errno=%d\n", EW_WIFI_AT_DEV, errno);
    return -1;
  }

  if (tcgetattr(fd, &tio) == 0) {
    cfmakeraw(&tio);
    cfsetispeed(&tio, B115200);
    cfsetospeed(&tio, B115200);
    tio.c_cflag |= (CLOCAL | CREAD);
    tio.c_cc[VMIN] = 0;
    tio.c_cc[VTIME] = 1;
    tcsetattr(fd, TCSANOW, &tio);
  }
  tcflush(fd, TCIOFLUSH);
  return fd;
}

static int resp_fail(const char *s)
{
  return strstr(s, "ERROR") != NULL || strstr(s, "FAIL") != NULL;
}

static int resp_ok(const char *s)
{
  return strstr(s, "OK") != NULL;
}

static int resp_got_ip(const char *s)
{
  return strstr(s, "WIFI GOT IP") != NULL ||
         strstr(s, "GOT IP") != NULL ||
         strstr(s, "smartconfig connected") != NULL;
}

static int read_until(int fd, char *out, unsigned out_sz, int timeout_ms, int want_ip)
{
  unsigned n = 0;
  int waited = 0;

  if (out_sz == 0) {
    return -1;
  }
  out[0] = '\0';
  while (waited < timeout_ms && n + 1 < out_sz) {
    char c;
    int r = read(fd, &c, 1);
    if (r == 1) {
      out[n++] = c;
      out[n] = '\0';
      if (resp_got_ip(out)) {
        return (int)n;
      }
      if (resp_fail(out)) {
        return (int)n;
      }
      if (!want_ip && resp_ok(out)) {
        return (int)n;
      }
      waited = 0;
    } else {
      usleep(20000);
      waited += 20;
    }
  }
  return (int)n;
}

static int at_tx(int fd, const char *line, char *resp, unsigned resp_sz,
                 int timeout_ms, int want_ip)
{
  char tx[192];
  int m;

  m = snprintf(tx, sizeof(tx), "%s\r\n", line);
  if (m > 0) {
    (void)write(fd, tx, (size_t)m);
  }
  if (strstr(line, "CWJAP") != NULL) {
    printf("[ew-at] tx=AT+CWJAP=***\n");
  } else {
    printf("[ew-at] tx=%s\n", line);
  }
  fflush(stdout);
  return read_until(fd, resp, resp_sz, timeout_ms, want_ip);
}

static int wait_gt(int fd, int timeout_ms)
{
  char buf[96];
  unsigned n = 0;
  int waited = 0;

  buf[0] = '\0';
  while (waited < timeout_ms && n + 1 < sizeof(buf)) {
    char c;
    int r = read(fd, &c, 1);
    if (r == 1) {
      buf[n++] = c;
      buf[n] = '\0';
      if (strchr(buf, '>') != NULL) {
        return 0;
      }
      if (resp_fail(buf)) {
        return -1;
      }
      waited = 0;
    } else {
      usleep(20000);
      waited += 20;
    }
  }
  return -1;
}

static int collect_bytes(int fd, char *out, unsigned out_sz, int timeout_ms)
{
  unsigned n = 0;
  int waited = 0;

  if (out_sz == 0) {
    return -1;
  }
  out[0] = '\0';
  while (waited < timeout_ms && n + 1 < out_sz) {
    char c;
    int r = read(fd, &c, 1);
    if (r == 1) {
      out[n++] = c;
      out[n] = '\0';
      waited = 0;
      if (n > 24 && strstr(out, "CLOSED") != NULL) {
        return (int)n;
      }
    } else {
      usleep(20000);
      waited += 20;
    }
  }
  return (int)n;
}

int ew_wifi_at_cmd(const char *at_line)
{
  char line[160];
  char resp[256];
  int fd;
  int n;
  size_t len;

  if (at_line == NULL || at_line[0] == '\0') {
    at_line = "AT";
  }
  snprintf(line, sizeof(line), "%s", at_line);
  len = strlen(line);
  while (len > 0 && (line[len - 1] == '\r' || line[len - 1] == '\n')) {
    line[--len] = '\0';
  }

  at_lock();
  fd = uart_open();
  if (fd < 0) {
    at_unlock();
    return 1;
  }
  n = at_tx(fd, line, resp, sizeof(resp), 2500, 0);
  close(fd);
  at_unlock();
  print_rx(resp);
  if (n > 0 && (resp_ok(resp) || resp_got_ip(resp))) {
    return 0;
  }
  if (n <= 0) {
    printf("[ew-at] no reply\n");
  }
  return (n > 0) ? 2 : 3;
}

int ew_wifi_at_ping(void)
{
  return ew_wifi_at_cmd("AT");
}

int ew_wifi_at_status(void)
{
  int rc = 0;

  printf("[ew-at] --- status ---\n");
  if (ew_wifi_at_cmd("AT+CWJAP?") != 0) {
    rc = 2;
  }
  if (ew_wifi_at_cmd("AT+CIFSR") != 0) {
    rc = 2;
  }
  if (ew_wifi_at_cmd("AT+CIPSTATUS") != 0) {
    rc = 2;
  }
  return rc;
}

int ew_wifi_bringup(char *out, unsigned out_sz)
{
  char resp[320];
  char jap[192];
  int fd;
  int n;

  if (out != NULL && out_sz > 0) {
    out[0] = '\0';
  }

  at_lock();
  fd = uart_open();
  if (fd < 0) {
    at_unlock();
    if (out != NULL && out_sz > 0) {
      snprintf(out, out_sz, "AT FAIL");
    }
    return 1;
  }

  (void)at_tx(fd, "AT", resp, sizeof(resp), 800, 0);
  n = at_tx(fd, "AT", resp, sizeof(resp), 2500, 0);
  print_rx(resp);
  if (n <= 0 || !resp_ok(resp)) {
    close(fd);
    at_unlock();
    if (out != NULL && out_sz > 0) {
      snprintf(out, out_sz, "AT FAIL");
    }
    printf("[ew-at] ping fail\n");
    return 2;
  }

  (void)at_tx(fd, "ATE0", resp, sizeof(resp), 800, 0);
  (void)at_tx(fd, "AT+CWMODE=1", resp, sizeof(resp), 1500, 0);

  if (EW_WIFI_SSID[0] != '\0') {
    snprintf(jap, sizeof(jap), "AT+CWJAP=\"%s\",\"%s\"", EW_WIFI_SSID, EW_WIFI_PASS);
    n = at_tx(fd, jap, resp, sizeof(resp), 20000, 1);
    close(fd);
    at_unlock();
    if (n > 0 && (resp_got_ip(resp) || resp_ok(resp)) && !resp_fail(resp)) {
      if (out != NULL && out_sz > 0) {
        snprintf(out, out_sz, "WIFI OK");
      }
      printf("[ew-at] join ok\n");
      return 0;
    }
    if (out != NULL && out_sz > 0) {
      snprintf(out, out_sz, "WIFI FAIL");
    }
    printf("[ew-at] join fail\n");
    return 3;
  }

  n = at_tx(fd, "AT+CWSTARTSMART=3", resp, sizeof(resp), 2000, 0);
  if (n <= 0 || !resp_ok(resp)) {
    close(fd);
    at_unlock();
    if (out != NULL && out_sz > 0) {
      snprintf(out, out_sz, "AT OK");
    }
    printf("[ew-at] smart start fail, AT still ok\n");
    return 0;
  }

  n = read_until(fd, resp, sizeof(resp), 40000, 1);
  (void)at_tx(fd, "AT+CWSTOPSMART", resp, sizeof(resp), 1500, 0);
  close(fd);
  at_unlock();

  if (n > 0 && resp_got_ip(resp)) {
    if (out != NULL && out_sz > 0) {
      snprintf(out, out_sz, "WIFI OK");
    }
    printf("[ew-at] smart ok\n");
    return 0;
  }
  if (out != NULL && out_sz > 0) {
    snprintf(out, out_sz, "AT OK");
  }
  printf("[ew-at] smart timeout, AT ok\n");
  return 0;
}

int ew_wifi_http_ssl_post(const char *host, unsigned port, const char *path,
                          const char *bearer, const char *json_body,
                          char *resp, unsigned resp_sz)
{
  char cmd[192];
  char http[1800];
  char scratch[512];
  char *dst;
  unsigned dst_sz;
  int fd;
  int n;
  unsigned blen;
  unsigned hlen;

  if (host == NULL || path == NULL || json_body == NULL) {
    return -1;
  }
  if (port == 0) {
    port = 443;
  }
  blen = (unsigned)strlen(json_body);
  hlen = (unsigned)snprintf(http, sizeof(http),
                            "POST %s HTTP/1.1\r\n"
                            "Host: %s\r\n"
                            "Authorization: Bearer %s\r\n"
                            "Content-Type: application/json\r\n"
                            "Connection: close\r\n"
                            "Content-Length: %u\r\n"
                            "\r\n"
                            "%s",
                            path, host, bearer ? bearer : "", blen, json_body);
  if (hlen >= sizeof(http) - 1) {
    printf("[ew-at] http too long\n");
    return -1;
  }

  dst = (resp != NULL && resp_sz > 8) ? resp : scratch;
  dst_sz = (resp != NULL && resp_sz > 8) ? resp_sz : sizeof(scratch);
  dst[0] = '\0';

  at_lock();
  fd = uart_open();
  if (fd < 0) {
    at_unlock();
    return -1;
  }

  (void)at_tx(fd, "ATE0", scratch, sizeof(scratch), 800, 0);
  (void)at_tx(fd, "AT", scratch, sizeof(scratch), 1500, 0);
  if (!resp_ok(scratch)) {
    print_rx(scratch);
    close(fd);
    at_unlock();
    printf("[ew-at] http ping fail\n");
    return -1;
  }
  (void)at_tx(fd, "AT+CIPMUX=0", scratch, sizeof(scratch), 1500, 0);
  (void)at_tx(fd, "AT+CIPMODE=0", scratch, sizeof(scratch), 1500, 0);
  (void)at_tx(fd, "AT+CIPCLOSE", scratch, sizeof(scratch), 1500, 0);
  (void)at_tx(fd, "AT+CIPSSLCCONF=0", scratch, sizeof(scratch), 1500, 0);

  snprintf(cmd, sizeof(cmd), "AT+CIPSTART=\"SSL\",\"%s\",%u", host, port);
  n = at_tx(fd, cmd, scratch, sizeof(scratch), 12000, 0);
  print_rx(scratch);
  if (n <= 0 || resp_fail(scratch) ||
      (strstr(scratch, "CONNECT") == NULL && !resp_ok(scratch))) {
    close(fd);
    at_unlock();
    printf("[ew-at] SSL CIPSTART fail\n");
    return -1;
  }

  snprintf(cmd, sizeof(cmd), "AT+CIPSEND=%u", hlen);
  n = at_tx(fd, cmd, scratch, sizeof(scratch), 2000, 0);
  if (strchr(scratch, '>') == NULL && wait_gt(fd, 3000) != 0) {
    close(fd);
    at_unlock();
    printf("[ew-at] CIPSEND no >\n");
    return -1;
  }
  (void)write(fd, http, (size_t)hlen);
  n = collect_bytes(fd, dst, dst_sz, 25000);
  (void)at_tx(fd, "AT+CIPCLOSE", scratch, sizeof(scratch), 1500, 0);
  close(fd);
  at_unlock();

  printf("[ew-at] http bytes=%d\n", n);
  return (n > 16) ? 0 : -1;
}

