int ew_wifi_smartconfig(char *out, unsigned out_sz)
{
  char resp[320];
  int fd;
  int n;

  if (ew_wifi_bringup(out, out_sz) != 0) {
    return 2;
  }

  at_lock();
  fd = uart_open();
  if (fd < 0) {
    at_unlock();
    return 1;
  }
  n = at_tx(fd, "AT+CWSTARTSMART=3", resp, sizeof(resp), 2000, 0);
  if (n <= 0 || !resp_ok(resp)) {
    close(fd);
    at_unlock();
    printf("[ew-at] smart start fail\n");
    return 3;
  }
  n = read_until(fd, resp, sizeof(resp), 40000, 1);
  (void)at_tx(fd, "AT+CWSTOPSMART", resp, sizeof(resp), 1500, 0);
  close(fd);
  at_unlock();
  if (n > 0 && resp_got_ip(resp)) {
    if (out != NULL && out_sz > 0) {
      snprintf(out, out_sz, "WIFI OK");
    }
    printf("[ew-at] smart ok\n");
    return 0;
  }
  if (out != NULL && out_sz > 0) {
    snprintf(out, out_sz, "AT OK");
  }
  printf("[ew-at] smart timeout\n");
  return 4;
}

